function Invoke-Psql {
    <# .SYNOPSIS Runs psql (never prompting) as a role; the password goes only through the child's PGPASSWORD. Generated Nov-01-2026. #>
    param(
        [Parameter(Mandatory)]$Config, [Parameter(Mandatory)][string]$User, [Parameter(Mandatory)][securestring]$Password,
        [Parameter(Mandatory)][string]$Database, [string[]]$Arguments = @(), [hashtable]$ExtraEnv = @{}, [switch]$AllowFailure
    )
    $vars = @{ PGPASSWORD = $Password } + $ExtraEnv
    $base = @('-X', '-w', '-v', 'ON_ERROR_STOP=1', '-h', $Config.PgHost, '-p', [string]$Config.PgPort, '-U', $User, '-d', $Database)
    $script:psqlResult = $null
    Invoke-WithSecretEnv -Variables $vars -ScriptBlock {
        $script:psqlResult = Invoke-Native -FilePath $Config.PsqlPath -Arguments ($base + $Arguments) -AllowFailure:$AllowFailure
    }
    return $script:psqlResult
}

function Get-DatabaseState {
    <# .SYNOPSIS Read-only report of whether the roles and database already exist (needs admin credentials). Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$AdminPassword)
    $sql = "SELECT (SELECT count(*) FROM pg_roles WHERE rolname IN ('$($Config.DeployRole)','$($Config.RuntimeRole)')) || ',' || (SELECT count(*) FROM pg_database WHERE datname='$($Config.Database)')"
    $out = (Invoke-Psql -Config $Config -User $Config.PgAdminUser -Password $AdminPassword -Database postgres -Arguments @('-tA', '-c', $sql)).Output
    $parts = ("$($out | Select-Object -First 1)").Trim() -split ','
    return [pscustomobject]@{ RolesPresent = [int]$parts[0]; DatabasePresent = ([int]$parts[1] -eq 1) }
}

function Invoke-DatabaseProvision {
    <# .SYNOPSIS After approval, idempotently creates missing roles/database via provision-idempotent.psql, preserving existing data. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$AdminPassword,
          [Parameter(Mandatory)][securestring]$DeployPassword, [Parameter(Mandatory)][securestring]$RuntimePassword, [switch]$HardenExisting)
    if ($Config.PsqlMajor -lt 15) { throw "psql 15 or newer is required (\getenv); found major $($Config.PsqlMajor)." }
    $file = Join-Path $Config.ScriptRoot 'provision-idempotent.psql'
    $args = @('-v', "db=$($Config.Database)", '-v', "deploy_role=$($Config.DeployRole)", '-v', "runtime_role=$($Config.RuntimeRole)", '-v', "harden=$([int][bool]$HardenExisting)", '-f', $file)
    Invoke-Psql -Config $Config -User $Config.PgAdminUser -Password $AdminPassword -Database postgres -Arguments $args `
        -ExtraEnv @{ GM_DEPLOY_PW = $DeployPassword; GM_RUNTIME_PW = $RuntimePassword } | Out-Null
}

