    return ((Invoke-Psql -Config $Config -User $User -Password $Password -Database $Config.Database -Arguments @('-tA', '-c', 'SELECT 1') -AllowFailure).ExitCode -eq 0)
}

function Invoke-SchemaMigration {
    <# .SYNOPSIS Runs the existing server\dist\migrate.js as the deploy role with explicit PG* env and no DATABASE_URL, then applies grant-runtime.sql. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$DeployPassword)
    $migrate = Join-Path $Config.AppRoot 'server\dist\migrate.js'
    if (-not (Test-Path -LiteralPath $migrate)) { throw "Missing $migrate; build the server first." }
    $saved = [Environment]::GetEnvironmentVariable('DATABASE_URL', 'Process')
    [Environment]::SetEnvironmentVariable('DATABASE_URL', $null, 'Process')
    try {
        Invoke-WithSecretEnv -Variables @{ PGHOST = $Config.PgHost; PGPORT = $Config.PgPort; PGDATABASE = $Config.Database; PGUSER = $Config.DeployRole
            PGPASSWORD = $DeployPassword; MIGRATIONS_ON_START = 'false' } -ScriptBlock {
            Invoke-Native -FilePath $Config.NodePath -Arguments @($migrate) | Out-Null
        }
    } finally { [Environment]::SetEnvironmentVariable('DATABASE_URL', $saved, 'Process') }
    Invoke-Psql -Config $Config -User $Config.DeployRole -Password $DeployPassword -Database $Config.Database `
        -Arguments @('-f', (Join-Path $Config.ScriptRoot 'grant-runtime.sql')) | Out-Null
}

function Get-RuntimeEnvText {
    <# .SYNOPSIS Builds runtime.env text from runtime.env.example with connection values, host, port and the runtime password substituted. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$RuntimePassword)
    $lines = Get-Content -LiteralPath (Join-Path $Config.ScriptRoot 'runtime.env.example')
    $map = @{ PGHOST = $Config.PgHost; PGPORT = [string]$Config.PgPort; PGDATABASE = $Config.Database; PGUSER = $Config.RuntimeRole
              PGPASSWORD = (ConvertTo-PlainText $RuntimePassword); PORT = [string]$Config.ApiPort; HOST = '127.0.0.1'; MIGRATIONS_ON_START = 'false' }
    $out = foreach ($line in $lines) {
        if ($line -match '^([A-Z_]+)=') { if ($map.ContainsKey($Matches[1])) { "$($Matches[1])=$(ConvertTo-DotEnvValue $map[$Matches[1]])" } else { $line } } else { $line }
    }
    return (($out -join "`r`n") + "`r`n")
}

function Test-RuntimeEnvFile {
    <# .SYNOPSIS Validates an existing runtime.env (quoted values and export prefixes understood) without altering it, including a weak-password check; returns a list of problems. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)]$Config)
    $problems = @()
    $e = ConvertFrom-DotEnv -Text (Get-Content -LiteralPath $Path -Raw)
    if ($e.ContainsKey('DATABASE_URL')) { $problems += 'DATABASE_URL must not be set (it overrides PG* values).' }
    if ($e['NODE_TLS_REJECT_UNAUTHORIZED'] -eq '0') { $problems += 'NODE_TLS_REJECT_UNAUTHORIZED=0 is forbidden.' }
    $expected = @{ MIGRATIONS_ON_START = 'false'; HOST = '127.0.0.1'; PGUSER = $Config.RuntimeRole; PGDATABASE = $Config.Database; PORT = [string]$Config.ApiPort }
    foreach ($k in $expected.Keys) { if ($e[$k] -ne $expected[$k]) { $problems += "Expected $k=$($expected[$k])" } }
    $pw = $e['PGPASSWORD']
    if (-not $pw -or $pw -eq 'REPLACE_ON_SERVER_ONLY' -or $pw.Length -lt 12 -or $pw -in @('postgres', 'password', $Config.RuntimeRole)) { $problems += 'PGPASSWORD is missing, a placeholder or weak (needs 12+ characters).' }
    if (-not $e.ContainsKey('WHATSAPP_STATUS_TEMPLATE')) { $problems += 'WHATSAPP_STATUS_TEMPLATE is missing; add WHATSAPP_STATUS_TEMPLATE=bike_service_status (not changed automatically).' }
    return $problems
}
function Install-RuntimeEnvFile {
    <# .SYNOPSIS Creates runtime.env once (never overwrites) inside the ACL-restricted secrets directory; validates an existing file instead. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config, [securestring]$RuntimePassword)
    if (Test-Path -LiteralPath $Config.EnvFile) {
        $problems = Test-RuntimeEnvFile -Path $Config.EnvFile -Config $Config
        foreach ($p in $problems) { Write-Warning "runtime.env: $p" }
        if ($problems | Where-Object { $_ -notmatch 'WHATSAPP_STATUS_TEMPLATE' }) { throw 'Existing runtime.env is unsafe, weak or mismatched; fix it manually (it is never overwritten or restored from defaults).' }
        return
    }
    if (-not $RuntimePassword) { throw 'runtime.env is missing and no runtime password was supplied.' }
    if ($PSCmdlet.ShouldProcess($Config.EnvFile, 'Create runtime.env with garage_runtime credentials')) {
        New-Item -ItemType File -Path $Config.EnvFile | Out-Null
        Invoke-Native -FilePath 'icacls.exe' -Arguments @($Config.EnvFile, '/inheritance:r', '/grant:r', '*S-1-5-32-544:F', '*S-1-5-18:F', '*S-1-5-19:R') | Out-Null
        [IO.File]::WriteAllText($Config.EnvFile, (Get-RuntimeEnvText -Config $Config -RuntimePassword $RuntimePassword), (New-Object Text.UTF8Encoding $false))
    }
}

function Get-UserCount {
    <# .SYNOPSIS Counts rows in users as the deploy role so bootstrap runs only on an empty database. Generated Nov-01-2026. #>
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$DeployPassword)
    $out = (Invoke-Psql -Config $Config -User $Config.DeployRole -Password $DeployPassword -Database $Config.Database -Arguments @('-tA', '-c', 'SELECT count(*) FROM users')).Output
    return [int]("$($out | Select-Object -First 1)".Trim())
}

function Install-LicensePublicKey {
    <# .SYNOPSIS Installs only an issuer public key after approval and updates only its runtime setting; private signing keys never belong on the server. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config)
    $verify = 'const fs=require(''node:fs''),crypto=require(''node:crypto'');const p=fs.readFileSync(process.argv[1],''utf8'');if(!p.includes(''-----BEGIN PUBLIC KEY-----'')||p.includes(''PRIVATE KEY''))throw Error(''Only a public key may be installed'');if(crypto.createPublicKey(p).asymmetricKeyType!==''ed25519'')throw Error(''Ed25519 public key required'');'
    $originalLines = @(Get-Content -LiteralPath $Config.EnvFile)
    if (@($originalLines | Where-Object { $_ -match '^\s*(?:export\s+)?LICENSE_PUBLIC_KEY_FILE\s*=' }).Count -gt 1) {
        throw 'Duplicate LICENSE_PUBLIC_KEY_FILE settings; fix the environment file manually.'
    }
    $settings = ConvertFrom-DotEnv -Text ($originalLines -join "`n")
    if (-not $Config.LicensePublicKeyPath) {
        if ($settings['LICENSE_PUBLIC_KEY_FILE']) {
            Invoke-Native -FilePath $Config.NodePath -Arguments @('-e', $verify, $settings['LICENSE_PUBLIC_KEY_FILE']) | Out-Null
            Write-Info 'Existing issuer public key validated; licensing configuration preserved.'
        } else {
            Write-Warning 'No issuer public key supplied. Trials last 30 days, but activation requires LICENSE_PUBLIC_KEY_FILE; see licensing\README.md.'
        }
        return
    }
    $source = (Get-Item -LiteralPath $Config.LicensePublicKeyPath -ErrorAction Stop).FullName
    Invoke-Native -FilePath $Config.NodePath -Arguments @('-e', $verify, $source) | Out-Null
    $destination = Join-Path $Config.SecretsDir 'issuer-public.pem'
    if ($settings['LICENSE_PUBLIC_KEY_FILE'] -and $settings['LICENSE_PUBLIC_KEY_FILE'] -ne $destination) {
        throw 'An existing issuer public key path is configured. Review key rotation manually; it is not overwritten.'
    }
    if ((Test-Path -LiteralPath $destination) -and
        (Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash -ne (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash) {
        throw 'A different issuer public key is already installed. Review key rotation manually.'
    }
    if (-not $PSCmdlet.ShouldProcess($destination, 'Install issuer public key and set LICENSE_PUBLIC_KEY_FILE')) { return }
    if (-not (Request-Approval -Action 'Install license issuer public key' -Target $destination -Detail 'The private signing key must remain on the issuer computer.' -Required)) { return }
    if (-not (Test-Path -LiteralPath $destination)) {
        Copy-Item -LiteralPath $source -Destination $destination
        Invoke-Native -FilePath 'icacls.exe' -Arguments @($destination, '/inheritance:r', '/grant:r', '*S-1-5-32-544:F', '*S-1-5-18:F', '*S-1-5-19:R') | Out-Null
    }
    $found = 0
    $lines = foreach ($line in $originalLines) {
        if ($line -match '^\s*(?:export\s+)?LICENSE_PUBLIC_KEY_FILE\s*=') {
            $found++
            "LICENSE_PUBLIC_KEY_FILE=$(ConvertTo-DotEnvValue $destination)"
        } else { $line }
    }
    if ($found -eq 0) { $lines = @($lines) + "LICENSE_PUBLIC_KEY_FILE=$(ConvertTo-DotEnvValue $destination)" }
    [IO.File]::WriteAllText($Config.EnvFile, (($lines -join "`r`n") + "`r`n"), (New-Object Text.UTF8Encoding $false))
}

function Invoke-OwnerBootstrap {
    <# .SYNOPSIS After approval and only when there are zero users, runs the existing bootstrap.js with prompted owner credentials. Generated Nov-01-2026. #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)]$Config, [Parameter(Mandatory)][securestring]$DeployPassword)
    if ((Get-UserCount -Config $Config -DeployPassword $DeployPassword) -gt 0) { Write-Info 'Accounts already exist; bootstrap skipped.'; return }
    if (-not (Request-Approval -Action 'Create the first garage owner account' -Target $Config.Database -Detail 'The users table is empty. You will be prompted for the owner email and a 12+ character password.')) { return }
    $email = Read-Host 'Garage owner email'
    $password = Read-SecretPrompt -Prompt 'New garage owner password (12+ characters)' -MinimumLength 12
    Invoke-WithSecretEnv -Variables @{ BOOTSTRAP_EMAIL = $email; BOOTSTRAP_PASSWORD = $password } -ScriptBlock {
        Invoke-Native -FilePath $Config.NodePath -Arguments @("--env-file=$($Config.EnvFile)", (Join-Path $Config.AppRoot 'server\dist\bootstrap.js')) | Out-Null
    }
}
